import{_ as t,c as a,o as n,ae as o}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"CMS Page — Create","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-cms-pages-create","title":"Create a CMS Page","description":"Top-level fields are broadcast to every locale at creation.","query":"mutation CreateCmsPage($input: createAdminCmsPageInput!) {\\n  createAdminCmsPage(input: $input) {\\n    adminCmsPage {\\n      id\\n      _id\\n      urlKey\\n      pageTitle\\n      htmlContent\\n      metaTitle\\n      metaKeywords\\n      metaDescription\\n      locale\\n      previewUrl\\n      createdAt\\n      updatedAt\\n      translations {\\n        edges {\\n          node {\\n            locale\\n            urlKey\\n            pageTitle\\n            htmlContent\\n            metaTitle\\n            metaKeywords\\n            metaDescription\\n          }\\n        }\\n      }\\n      channels {\\n        edges {\\n          node {\\n            _id\\n            code\\n            name\\n          }\\n        }\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"urlKey\\": \\"about-us\\",\\n    \\"pageTitle\\": \\"About Us\\",\\n    \\"htmlContent\\": \\"<h1>About Us</h1>\\",\\n    \\"metaTitle\\": \\"About Us\\",\\n    \\"metaKeywords\\": \\"about,us,company\\",\\n    \\"metaDescription\\": \\"Learn more about our company.\\",\\n    \\"channels\\": [1]\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminCmsPage\\": {\\n      \\"adminCmsPage\\": {\\n        \\"id\\": \\"/api/admin/cms/pages/7\\",\\n        \\"_id\\": 7,\\n        \\"urlKey\\": \\"about-us\\",\\n        \\"pageTitle\\": \\"About Us\\",\\n        \\"htmlContent\\": \\"<h1>About Us</h1>\\",\\n        \\"metaTitle\\": \\"About Us\\",\\n        \\"metaKeywords\\": \\"about,us,company\\",\\n        \\"metaDescription\\": \\"Learn more about our company.\\",\\n        \\"locale\\": \\"en\\",\\n        \\"previewUrl\\": \\"https://store.example.com/page/about-us\\",\\n        \\"createdAt\\": \\"2026-06-23T11:49:19+00:00\\",\\n        \\"updatedAt\\": \\"2026-06-23T11:49:19+00:00\\",\\n        \\"translations\\": {\\n          \\"edges\\": [\\n            {\\n              \\"node\\": {\\n                \\"locale\\": \\"en\\",\\n                \\"urlKey\\": \\"about-us\\",\\n                \\"pageTitle\\": \\"About Us\\",\\n                \\"htmlContent\\": \\"<h1>About Us</h1>\\",\\n                \\"metaTitle\\": \\"About Us\\",\\n                \\"metaKeywords\\": \\"about,us,company\\",\\n                \\"metaDescription\\": \\"Learn more about our company.\\"\\n              }\\n            }\\n          ]\\n        },\\n        \\"channels\\": {\\n          \\"edges\\": [\\n            { \\"node\\": { \\"_id\\": 1, \\"code\\": \\"default\\", \\"name\\": \\"Default\\" } }\\n          ]\\n        }\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/cms/pages/mutations/create.md","filePath":"api/graphql-api/admin/cms/pages/mutations/create.md"}'),d={name:"api/graphql-api/admin/cms/pages/mutations/create.md"};function r(s,e,i,c,l,p){return n(),a("div",null,e[0]||(e[0]=[o('<h1 id="cms-page-—-create" tabindex="-1">CMS Page — Create <a class="header-anchor" href="#cms-page-—-create" aria-label="Permalink to &quot;CMS Page — Create&quot;">​</a></h1><p>Creates a new CMS page. Equivalent to <a href="/api/rest-api/admin/cms/pages-create.html"><code>POST /api/admin/cms/pages</code></a>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>createAdminCmsPage</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><p>GraphQL input fields are <strong>camelCase</strong>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>urlKey</code></td><td><code>String!</code></td><td>yes</td><td>Unique slug (lowercase, hyphen-separated). Serves the page at <code>/page/{urlKey}</code>.</td></tr><tr><td><code>pageTitle</code></td><td><code>String!</code></td><td>yes</td><td></td></tr><tr><td><code>htmlContent</code></td><td><code>String!</code></td><td>yes</td><td>Page body (HTML).</td></tr><tr><td><code>channels</code></td><td><code>[Int!]!</code></td><td>yes</td><td>Non-empty list of channel IDs the page is published to.</td></tr><tr><td><code>metaTitle</code></td><td><code>String</code></td><td>no</td><td></td></tr><tr><td><code>metaKeywords</code></td><td><code>String</code></td><td>no</td><td></td></tr><tr><td><code>metaDescription</code></td><td><code>String</code></td><td>no</td><td></td></tr></tbody></table><h2 id="broadcast-to-every-locale" tabindex="-1">Broadcast to every locale <a class="header-anchor" href="#broadcast-to-every-locale" aria-label="Permalink to &quot;Broadcast to every locale&quot;">​</a></h2><p>Create takes <strong>flat top-level fields</strong> and <strong>broadcasts them to every configured locale</strong> — the new page starts with the same <code>pageTitle</code> / <code>htmlContent</code> / <code>urlKey</code> / SEO values in each language. Translate individual languages afterwards with <a href="/api/graphql-api/admin/cms/pages/mutations/update.html">Update</a> (which is locale-nested).</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p>The mutation returns the <strong>created page</strong>. All scalars resolve, and <code>translations</code> / <code>channels</code> are <strong>field-selectable connections</strong> (<code>{ edges { node { … } } }</code>) — <code>translations</code> carries one entry per configured locale (the broadcast content). Select only what you need.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td><code>urlKey</code>, <code>pageTitle</code>, or <code>htmlContent</code> missing</td><td>validation error</td></tr><tr><td><code>urlKey</code> not a valid slug, or already in use</td><td>validation error</td></tr><tr><td><code>channels</code> empty or contains an unknown ID</td><td>validation error</td></tr><tr><td>Admin role lacks <code>cms.create</code></td><td>permission error</td></tr></tbody></table>',13)]))}const u=t(d,[["render",r]]);export{h as __pageData,u as default};
